<?php
get_header();while(have_posts()):the_post();global $product;if(!$product)$product=wc_get_product(get_the_ID());$pid=$product->get_id();$bhopts=get_option('bhc_options',[]);$payload=['id'=>$pid,'title'=>$product->get_name(),'url'=>get_permalink($pid),'price'=>wp_strip_all_tags($product->get_price_html()),'image'=>get_the_post_thumbnail_url($pid,'large')?:wc_placeholder_img_src(),'sku'=>$product->get_sku(),'specs'=>[]];foreach($product->get_attributes() as $a){$vals=$a->is_taxonomy()?wc_get_product_terms($pid,$a->get_name(),['fields'=>'names']):$a->get_options();if($vals)$payload['specs'][wc_attribute_label($a->get_name())]=implode('، ',$vals);}$brand_name='';$brand_latin='';if(function_exists('bhb_brand_rows')){foreach(bhb_brand_rows() as $brand){$needles=array_filter([$brand['name']??'',$brand['latin']??'']);foreach($needles as $needle){if($needle!==''&&mb_stripos($product->get_name(),$needle)!==false){$brand_name=$brand['name'];$brand_latin=$brand['latin'];break 2;}}}}
?>
<div class="bhp-product wrap"><?php do_action('woocommerce_before_single_product');?><nav class="bhp-breadcrumb" aria-label="مسیر صفحه"><?php woocommerce_breadcrumb();?></nav><div class="bhp-product-main"><div class="bhp-gallery"><div class="bhp-main-image" id="bhp-main-image" aria-label="گالری تصاویر محصول"><?php echo wp_kses_post($product->get_image('woocommerce_single',['loading'=>'eager','fetchpriority'=>'high']));?><?php if($product->is_on_sale()):?><span class="bhp-sale-tag">تخفیف ویژه</span><?php endif;?></div><?php $gallery=$product->get_gallery_image_ids();if($gallery):?><div class="bhp-thumbs" role="list" aria-label="تصاویر کوچک محصول"><button type="button" class="is-active" data-image="<?php echo esc_url(get_the_post_thumbnail_url($pid,'woocommerce_single'));?>" aria-pressed="true"><?php echo wp_get_attachment_image(get_post_thumbnail_id($pid),'thumbnail',['loading'=>'lazy']);?></button><?php foreach($gallery as $img):?><button type="button" data-image="<?php echo esc_url(wp_get_attachment_image_url($img,'woocommerce_single'));?>" aria-pressed="false"><?php echo wp_get_attachment_image($img,'thumbnail',['loading'=>'lazy']);?></button><?php endforeach;?></div><?php endif;?></div><section class="bhp-product-info"><div class="bhp-product-cat"><?php echo wp_kses_post(wc_get_product_category_list($pid));?></div><h1><?php the_title();?></h1><div class="bhp-review-line"><?php if(!empty($bhopts['show_rating']))woocommerce_template_single_rating();?><span>شناسه کالا: <?php echo esc_html($product->get_sku()?:'—');?></span></div><div class="bhp-price-wrap"><?php woocommerce_template_single_price();?></div><div class="bhp-shortdesc"><?php woocommerce_template_single_excerpt();?></div><?php $highlights=get_post_meta($pid,'_bhc_highlights',true);if($highlights):?><ul class="bhp-highlights"><?php foreach(preg_split('/\r\n|\r|\n/',$highlights) as $h)if(trim($h))echo '<li>'.esc_html($h).'</li>';?></ul><?php endif;?><?php if($product->is_in_stock()):?><div class="bhp-availability" aria-live="polite"><i></i> موجود برای سفارش <small><?php echo $product->managing_stock()&&$product->get_stock_quantity()?'· '.$product->get_stock_quantity().' عدد در انبار':'';?></small></div><?php else:?><div class="bhp-availability is-out" aria-live="polite"><i></i> در حال حاضر ناموجود</div><?php endif;?><div class="bhp-cart-form" id="bhp-cart"><?php woocommerce_template_single_add_to_cart();?></div><div class="bhp-product-actions"><?php if(!empty($bhopts['show_wishlist'])):?><button type="button" class="bhp-wish" data-item="<?php echo esc_attr(wp_json_encode($payload));?>" aria-pressed="false">♡ افزودن به علاقه‌مندی</button><?php endif;?><?php if(!empty($bhopts['show_compare'])):?><button type="button" class="bhp-compare" data-item="<?php echo esc_attr(wp_json_encode($payload));?>" aria-pressed="false">⇄ مقایسه‌ی محصول</button><?php endif;?></div><div class="bhp-assurance"><?php $warranty=get_post_meta($pid,'_bhc_warranty',true);$ship_note=get_post_meta($pid,'_bhc_shipping_note',true);if($warranty):?><span>✓ <?php echo esc_html($warranty);?></span><?php endif;if($ship_note):?><span>↗ <?php echo esc_html($ship_note);?></span><?php endif;if(!empty($bhopts['phone'])||!empty($bhopts['whatsapp'])):?><span>✦ برای پرسش با پشتیبانی تماس بگیرید</span><?php endif;?></div></section></div>
<div class="bhp-detail-layout"><aside class="bhp-detail-nav"><a href="#bhp-desc">توضیحات محصول</a><a href="#bhp-specs">مشخصات فنی</a><a href="#bhp-reviews">دیدگاه خریداران</a><?php if(get_post_meta($pid,'_bhc_faq',true)):?><a href="#bhp-faq">پرسش‌های پرتکرار</a><?php endif;?></aside><div class="bhp-details"><section id="bhp-desc" class="bhp-detail-section"><span class="bhx-overline">درباره‌ی محصول</span><h2>آشنایی با <?php the_title();?></h2><div class="bhp-description"><?php the_content();?></div></section><section id="bhp-specs" class="bhp-detail-section"><span class="bhx-overline">اطلاعات فنی</span><h2>مشخصات محصول</h2><table class="bhp-spec-table"><tbody><?php if($product->get_sku()):?><tr><th>مدل / شناسه</th><td><?php echo esc_html($product->get_sku());?></td></tr><?php endif;?><?php if($product->has_weight()):?><tr><th>وزن</th><td><?php echo esc_html(wc_format_weight($product->get_weight()));?></td></tr><?php endif;?><?php if($product->has_dimensions()):?><tr><th>ابعاد</th><td><?php echo esc_html(wc_format_dimensions($product->get_dimensions(false)));?></td></tr><?php endif;?><?php foreach($product->get_attributes() as $a):$values=$a->is_taxonomy()?wc_get_product_terms($pid,$a->get_name(),['fields'=>'names']):$a->get_options();if(!$values)continue;?><tr><th><?php echo esc_html(wc_attribute_label($a->get_name()));?></th><td><?php echo esc_html(implode('، ',$values));?></td></tr><?php endforeach;?></tbody></table></section><section id="bhp-reviews" class="bhp-detail-section"><span class="bhx-overline">تجربه‌ی خریداران</span><h2>دیدگاه‌ها و امتیازها</h2><?php comments_template();?></section><?php $faq=get_post_meta($pid,'_bhc_faq',true);if($faq):?><section id="bhp-faq" class="bhp-detail-section"><span class="bhx-overline">پاسخ پیش از خرید</span><h2>پرسش‌های پرتکرار</h2><?php foreach(preg_split('/\r\n|\r|\n/', $faq) as $line):if(trim($line)){$pair=array_map('trim',explode('|',$line,2));echo '<details class="bhp-faq"><summary>'.esc_html($pair[0]).'</summary><p>'.esc_html($pair[1]??'برای پاسخ دقیق با پشتیبانی فروشگاه تماس بگیرید.').'</p></details>';}endforeach;?></section><?php endif;?></div></div><?php woocommerce_output_related_products(['posts_per_page'=>4,'columns'=>4]);?><div class="bhp-sticky-buy"><div><b><?php the_title();?></b><span><?php echo wp_kses_post($product->get_price_html());?></span></div><a href="#bhp-cart" class="bhp-sticky-cta"><?php echo $product->is_in_stock()?'رفتن به خرید':'مشاهده وضعیت';?></a></div></div>
<?php if(!defined('RANK_MATH_VERSION')&&!defined('WPSEO_VERSION')&&function_exists('WC')&&WC()->structured_data)WC()->structured_data->generate_product_data($product);do_action('woocommerce_after_single_product');endwhile;get_footer(); ?>
